const root = document.body;
const esc = value => String(value ?? '').replace(/[&<>"']/g, char => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
let selectedCityId = localStorage.getItem('tuka-meta-city') || 'boston';
let selectedStopId = '';
function ensurePanel() {
  if (document.querySelector('#meta-lab')) return document.querySelector('#meta-lab');
  const button = document.createElement('button'); button.id='meta-open'; button.className='meta-open'; button.type='button'; button.innerHTML='<span class="meta-orb">✦</span><span>Meta Copilot</span>'; button.setAttribute('aria-label','Open Tuka Meta Copilot'); document.querySelector('.headtools')?.prepend(button);
  const dialog = document.createElement('dialog'); dialog.id='meta-lab'; dialog.className='meta-dialog';
  dialog.innerHTML='<form method="dialog" class="meta-head"><div><span class="meta-kicker">META HACKATHON BUILD</span><h2>Tuka Copilot</h2><p>A city-aware transit assistant grounded in official network data. Boston is the featured demo.</p></div><button class="meta-close" aria-label="Close">×</button></form><section class="meta-city-section"><div class="meta-section-heading"><div><span class="meta-kicker">CITY-AWARE TRANSIT</span><h3>Choose a network profile</h3></div><span id="meta-city-status" class="meta-status">Loading…</span></div><div id="meta-cities" class="meta-cities"></div></section><section class="meta-chat"><div class="meta-section-heading"><div><span class="meta-kicker">GROUNDED ANSWERS</span><h3>Ask about the selected network</h3></div><span class="meta-lock">Token stays server-side</span></div><div class="meta-chat-log" id="meta-chat-log" aria-live="polite"><p class="meta-message meta-message-ai">Choose Boston to open the live MBTA demo, then ask me about its stops, schedule, or data freshness.</p></div><form id="meta-ask" class="meta-ask"><input id="meta-question" maxlength="1200" autocomplete="off" placeholder="e.g. What is live near my selected Boston stop?" aria-label="Ask Tuka Copilot"><button class="primary">Ask</button></form></section><p class="meta-footnote">Answers are grounded in Tuka’s verified city registry and live MBTA checks when a Boston stop is selected. Confirm departures in the planner before leaving.</p>';
  root.append(dialog); return dialog;
}
function cityCard(city, selected) { const live=city.capabilities.includes('realtime'); return `<button type="button" class="meta-city ${selected?'selected':''}" data-city-id="${esc(city.id)}" aria-pressed="${selected}"><span class="meta-city-top"><strong>${esc(city.name)}</strong><span class="meta-city-pill ${live?'live':''}">${live?'Live':'GTFS'}</span></span><small>${esc(city.provider)} · ${esc(city.timezone)}</small><span>${esc(city.description)}</span></button>`; }
async function selectCity(city, dialog) {
  selectedCityId = city.id;
  selectedStopId = '';
  localStorage.setItem('tuka-meta-city', city.id);
  dialog.querySelector('#meta-city-status').textContent = `Loading ${city.name} test data…`;
  if (city.id === 'boston') {
    try { const response = await fetch('./boston-snapshot.json', {credentials:'same-origin'}); if (!response.ok) throw Error(); const snapshot = await response.json(); document.dispatchEvent(new CustomEvent('tuka-test-city', {detail: {...city, ...snapshot, cityId: 'boston', lat: 42.3557, lon: -71.0629}})); dialog.querySelector('#meta-city-status').textContent = 'Boston demo active · click a stop on the map'; return; } catch { dialog.querySelector('#meta-city-status').textContent = 'Boston snapshot unavailable'; return; }
  }
  document.dispatchEvent(new CustomEvent('tuka-test-city', {detail: {cityId:'skopje'}}));
  dialog.querySelector('#meta-city-status').textContent = 'Skopje live location active';
}
async function loadCities(dialog) { const holder=dialog.querySelector('#meta-cities'); try { const response=await fetch('./api/cities',{headers:{Accept:'application/json'},credentials:'same-origin'}); if(!response.ok)throw Error(); const data=await response.json(); if(!(data.cities||[]).some(city=>city.id===selectedCityId))selectedCityId='boston'; holder.innerHTML=(data.cities||[]).map(city=>cityCard(city,city.id===selectedCityId)).join(''); dialog.querySelector('#meta-city-status').textContent=`${data.cities?.length||0} profiles · Boston is ready to explore`; holder.querySelectorAll('[data-city-id]').forEach(button=>button.addEventListener('click',()=>{const city=(data.cities||[]).find(item=>item.id===button.dataset.cityId);if(!city)return;holder.querySelectorAll('[data-city-id]').forEach(next=>{const active=next===button;next.classList.toggle('selected',active);next.setAttribute('aria-pressed',String(active));});selectCity(city,dialog);})); const initial=(data.cities||[]).find(city=>city.id===selectedCityId); if(initial)selectCity(initial,dialog); } catch { dialog.querySelector('#meta-city-status').textContent='Profiles unavailable'; holder.innerHTML='<p class="meta-empty">The protected profile service is unavailable. Skopje remains available in the main app.</p>'; } }
function addMessage(log,text,kind){const item=document.createElement('p');item.className=`meta-message meta-message-${kind}`;item.textContent=text;log.append(item);log.scrollTop=log.scrollHeight;}
function bindBostonRoutes(){document.querySelectorAll('.test-city-card .route-pill').forEach(button=>{if(button.dataset.tukaRouteBound)return;button.dataset.tukaRouteBound='1';button.setAttribute('role','button');button.setAttribute('tabindex','0');const activate=()=>{const route=button.querySelector('strong')?.textContent?.trim();if(route)document.dispatchEvent(new CustomEvent('tuka-test-route',{detail:{route}}));};button.addEventListener('click',activate);button.addEventListener('keydown',event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();activate();}});});}
new MutationObserver(bindBostonRoutes).observe(document.body,{subtree:true,childList:true});
function init(){const dialog=ensurePanel();document.querySelector('#meta-open').addEventListener('click',()=>{dialog.showModal();loadCities(dialog);});document.addEventListener('tuka-test-city-active',event=>{if(event.detail?.cityId)selectedCityId=event.detail.cityId;});document.addEventListener('tuka-test-stop-active',event=>{selectedStopId=String(event.detail?.stopId||'');});const form=dialog.querySelector('#meta-ask'),input=dialog.querySelector('#meta-question'),log=dialog.querySelector('#meta-chat-log');form.addEventListener('submit',async event=>{event.preventDefault();const message=input.value.trim();if(!message)return;input.value='';addMessage(log,message,'user');const submit=form.querySelector('button');submit.disabled=true;submit.textContent='Thinking…';try{const response=await fetch('./api/meta/ask',{method:'POST',headers:{'Content-Type':'application/json',Accept:'application/json'},credentials:'same-origin',body:JSON.stringify({message,cityId:selectedCityId,stopId:selectedStopId})});const data=await response.json().catch(()=>({}));addMessage(log,response.ok?data.answer:(data.error||'Meta Copilot is unavailable.'),response.ok?'ai':'error');}catch{addMessage(log,'Meta Copilot is unavailable. Use the planner for verified journey details.','error');}finally{submit.disabled=false;submit.textContent='Ask';}});}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init,{once:true});else init();
